I have a kernel that computes the correlation volume. It behaves as expected in cuda:0. But raises a CUDA_ERROR_ILLEGAL_ADDRESS error in cuda:1.

### To Reproduce

```py
import cupy
import re
import torch

device = 1


def cupy_kernel(strFunction, objVariables):
    strKernel = globals()[strFunction]

    while True:
        objMatch = re.search("(SIZE_)([0-4])(\()([^\)]*)(\))", strKernel)

        if objMatch is None:
            break
        # end

        intArg = int(objMatch.group(2))

        strTensor = objMatch.group(4)
        intSizes = objVariables[strTensor].size()

        strKernel = strKernel.replace(
            objMatch.group(),
            str(
                intSizes[intArg]
                if torch.is_tensor(intSizes[intArg]) == False
                else intSizes[intArg].item()
            ),
        )

    while True:
        objMatch = re.search("(VALUE_)([0-4])(\()([^\)]+)(\))", strKernel)

        if objMatch is None:
            break
        # end

        intArgs = int(objMatch.group(2))
        strArgs = objMatch.group(4).split(",")

        strTensor = strArgs[0]
        intStrides = objVariables[strTensor].stride()
        strIndex = [
            "(("
            + strArgs[intArg + 1].replace("{", "(").replace("}", ")").strip()
            + ")*"
            + str(
                intStrides[intArg]
                if torch.is_tensor(intStrides[intArg]) == False
                else intStrides[intArg].item()
            )
            + ")"
            for intArg in range(intArgs)
        ]

        strKernel = strKernel.replace(
            objMatch.group(0), strTensor + "[" + str.join("+", strIndex) + "]"
        )
    # end

    return strKernel


# end

